const ROLE_NAMES={system:'系統工程師',ai:'AI工程師',project:'專案經理',product:'產品經理',design:'設計師',bd:'商務開發',sales:'業務',mis:'MIS工程師',executive:'空降主管'};
const SYMBOLS=['職','副','管','督','首'];
export const CAREER_ENDINGS=CAREER_FAMILIES.flatMap((family,rank)=>STORIES[family.id].map(([roleId,title,subtitle,body])=>({
 id:`${family.id}-${roleId}`,family:family.id,roleId,title,subtitle,type:family.type,body,
 hint:`新版應徵${ROLE_NAMES[roleId]}；實際職務為正式職（非助理）、rank恰為${rank}，滿足該級任職條件後，從rank-exit選擇目前職級離場。`,
 symbol:SYMBOLS[rank]
})));
